class Solution {
  public long maximumSumOfHeights(int[] maxHeights) {
    int n = maxHeights.length;
    long[] left = new long[n], right = new long[n];
    Deque<Integer> stack = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
      while (!stack.isEmpty() && maxHeights[stack.peek()] > maxHeights[i]) stack.pop();
      int p = stack.isEmpty() ? -1 : stack.peek();
      left[i] = (p == -1 ? 0 : left[p]) + (long) (i - p) * maxHeights[i];
      stack.push(i);
    }
    stack.clear();
    for (int i = n - 1; i >= 0; i--) {
      while (!stack.isEmpty() && maxHeights[stack.peek()] > maxHeights[i]) stack.pop();
      int p = stack.isEmpty() ? n : stack.peek();
      right[i] = (p == n ? 0 : right[p]) + (long) (p - i) * maxHeights[i];
      stack.push(i);
    }
    long best = 0;
    for (int i = 0; i < n; i++) best = Math.max(best, left[i] + right[i] - maxHeights[i]);
    return best;
  }
}
